class ChildListQuery(BaseModel):
    """Typed service contract."""
    limit: int = Field(20, ge=1, le={{max_limit}})
    offset: int = Field(0, ge=0)
    {{filter_field}}: bool | None = None

@router.get({{path}}, response_model=list[ChildRead])
def list_child(parent_id: int, db: Annotated[Session, Depends(session_provider)], query: Annotated[ChildListQuery, Query()]) -> list[Child]:
    """List child."""
    require_parent(db, parent_id)
    statement = select(Child).where(Child.{{foreign_key}} == parent_id)
    if query.{{filter_field}} is not None:
        statement = statement.where(Child.{{filter_field}} == query.{{filter_field}})
    return list(db.scalars(statement.order_by(Child.id).limit(query.limit).offset(query.offset)))
